#include "AddMaterialDialog.hpp"
#include "ui_AddMaterialDialog.h" // file generated by the MOC

#include <fmt/core.h>


AddMaterialDialog::AddMaterialDialog(QWidget* parent)
: QDialog(parent)
, ui(new Ui::AddMaterialDialog) // class denefinition generated by the MOC
{
  ui->setupUi(this);

  m_doubleValidator.setBottom(0.0);

  for (int i = 1; i < 10; ++i)
  {
    auto* layoutItem = ui->materialFormLayout->itemAt(i, QFormLayout::ItemRole::FieldRole);
    auto* widget = layoutItem->widget();
    auto* lineEdit = qobject_cast<QLineEdit*>(widget);

    if (!lineEdit)
    {
      fmt::print("This line edit is ass.");
    }

    lineEdit->setValidator(&m_doubleValidator);
  }

  connect(ui->importMaterialButton, &QPushButton::clicked, this, &AddMaterialDialog::onImportMaterialButtonClicked);
}


AddMaterialDialog::~AddMaterialDialog()
{
}


void AddMaterialDialog::onImportMaterialButtonClicked()
{
  fmt::println("So, I herd u like importing materials :>");
}
